def is_permutation(a3, a1, p):
    vals = set()
    for x in range(p):
        vals.add((a3 * x**3 + a1 * x) % p)
    return len(vals) == p

def count_permutations(p):
    count = 0
    for a3 in range(p):
        for a1 in range(p):
            if is_permutation(a3, a1, p):
                count += 1
    return count

print(f"p=3: {count_permutations(3)}")
print(f"p=11: {count_permutations(11)}")
print(f"p=61: {count_permutations(61)}")

def is_perm_k(k, p):
    vals = set()
    for x in range(p):
        vals.add((x**3 + k*x) % p)
    return len(vals) == p

for p in [3, 11, 61]:
    k_vals = [k for k in range(p) if is_perm_k(k, p)]
    print(f"p={p}, k_vals={k_vals}, count={len(k_vals)}")

def count_permutations(p):
    count = 0
    for a3 in range(p):
        for a1 in range(p):
            vals = set()
            for x in range(p):
                vals.add((a3 * x**3 + a1 * x) % p)
            if len(vals) == p:
                count += 1
    return count

print(count_permutations(3) * count_permutations(11) * count_permutations(61))
